1|#!/usr/bin/env node
2|/***
3| * MARK: capture-screenshot.mjs
4| * @description Standalone headless Playwright utility for capturing deterministic
5| * screenshots during PR review or verification stages without running ad-hoc background servers.
6| *
7| * Usage:
8| *   node scripts/capture-screenshot.mjs --path "#/tasks/<task-id>"
9| *   node scripts/capture-screenshot.mjs --url "http://localhost:3100/#/orchestrator" --out "./docs/tasks/task-1/screenshot.png"
10| *   node scripts/capture-screenshot.mjs --path "#/tasks/9940bbbc" --out "./docs/tasks/9940bbbc/stage-review.png"
11| *
12| * Output default (no --out): resolves the current task id — $TASK_ID, else
13| *   $KAINBAIN_TASK_ID, else the kb/<task-id> branch name — and writes to
14| *   docs/tasks/<task-id>/screenshot-<YYYYMMDD-HHMMSS>.png (directory created).
15| *   An explicit --out always wins. With no discoverable id the script exits
16| *   non-zero naming the expected --out form instead of writing to repo root.
17| *   A default name already taken by an earlier same-second capture gains a
18| *   -01, -02, ... suffix instead of overwriting (explicit --out keeps
19| *   today's exact overwrite behavior). A flag token right after --out
20| *   counts as a missing value, never as a path.
21| *
22| * Fails fast (exit 1, before launching a browser) when no task id is
23| *   discoverable, when the id is unsafe for a path, or when all 99
24| *   same-second fallback names are taken — each message shows the --out
25| *   form to pass instead.
26| *
27| * Proof checklist (canonical rules: docs/agent-docs/GitGuidance.md):
28| *   1. This script writes bytes directly — never open the PNG in an editor
29| *      or rewrite it with a text-oriented tool (UTF-8 round-trips corrupt
30| *      it: magic `ef bf bd` instead of `89 50 4e 47`).
31| *   2. Before claiming validity: `xxd -l 8 <out>` (expect `8950 4e47…`)
32| *      and `file <out>` (expect `PNG image data`, not `data`).
33| *   3. This script self-verifies PNG magic right after writing and fails
34| *      fast when the write was interrupted — quote its `PNG magic
35| *      verified` line as the validity evidence, then run the pre-handoff
36| *      gate `npm run check:binaries` (CI re-verifies every proof image
37| *      via `npm run check:proof-hygiene`).
38| ***/
39|
40|import path from "node:path";
41|import fs from "node:fs";
42|import { execFileSync } from "node:child_process";
43|import { fileURLToPath } from "node:url";
44|
45|/***
46| * MARK: verifyPngMagic
47| * @description Verifies a capture wrote intact PNG bytes by comparing the
48| *   file's leading head against the PNG magic `89504e47`. Non-PNG outputs
49| *   are skipped, never failed; a missing or empty capture FAILS, so a
50| *   screenshot that never landed can never be claimed valid.
51| * @example verifyPngMagic("/repo/docs/tasks/x/shot-proof.png") => { ok: true, ... }
52| * @param {string} absPath - Absolute path of the capture output.
53| * @returns {{ ok: boolean, expected: string|null, actual: string|null, skipped?: string, error?: string }}
54| ***/
55|export function verifyPngMagic(absPath) {
56|	const fileExtension = path.extname(absPath).toLowerCase();
57|	if (fileExtension !== ".png") {
58|		return { ok: true, expected: null, actual: null, skipped: `not a PNG output (${fileExtension || "(none)"})` };
59|	}
60|	const expected = "89504e47";
61|	let pngHeadBytes;
62|	try {
63|		const fileDescriptor = fs.openSync(absPath, "r");
64|		try {
65|			const headBuffer = Buffer.alloc(8);
66|			const bytesRead = fs.readSync(fileDescriptor, headBuffer, 0, 8, 0);
67|			pngHeadBytes = headBuffer.subarray(0, bytesRead);
68|		} finally {
69|			fs.closeSync(fileDescriptor);
70|		}
71|	} catch (err) {
72|		const reason = err && err.code ? `${err.code}: ${absPath}` : `read failed: ${absPath}`;
73|		return { ok: false, expected, actual: null, error: reason };
74|	}
75|	const actual = pngHeadBytes.toString("hex").toLowerCase();
76|	const ok = actual.startsWith(expected);
77|	return ok
78|		? { ok, expected, actual }
79|		: { ok, expected, actual, error: `capture bytes do not start with PNG magic ${expected}` };
80|}
