82|/***
83| * MARK: sanitizeTaskId
84| * @description Checks one raw task-id candidate is safe to use as a single
85| *   folder name under docs/tasks/. Returns the trimmed id when it starts
86| *   with a letter or digit and holds only letters, digits, dots, dashes,
87| *   and underscores (covers UUIDs and short slugs like task-1); returns
88| *   null for anything else — empty values, separators, traversal (. / ..
89| *   / ../x), hidden names (.well-known), whitespace, or shell-hostile
90| *   characters — so callers treat it as "no id" and fail fast naming
91| *   --out instead of writing outside the task folder.
92| * @example sanitizeTaskId("  9940bbbc  ") => "9940bbbc"
93| * @example sanitizeTaskId("../x") => null
94| * @param {*} rawTaskId - One raw candidate (env value or branch segment).
95| * @returns {string|null} The safe id, or null when unusable.
96| ***/
97|export function sanitizeTaskId(rawTaskId) {
98|	if (rawTaskId === null || rawTaskId === undefined) return null;
99|	const candidateTaskId = String(rawTaskId).trim();
100|	if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(candidateTaskId)) return null;
101|	return candidateTaskId;
