105| * MARK: resolveTaskId
106| * @description Resolves the current task id for the no-flag default output:
107| *   $TASK_ID first, else $KAINBAIN_TASK_ID, else the kb/<task-id> branch
108| *   name. Empty values count as unset and fall through; a non-empty but
109| *   unsafe value resolves to null (fail fast) rather than falling through
110| *   to a different source or building a traversal path. Pure: env and branch
111| *   are injected so tests never touch process.env or git.
112| * @example resolveTaskId({ env: {}, branch: "kb/9940bbbc" }) => "9940bbbc"
113| * @param {Object} [opts]
114| * @param {Object} [opts.env] - Environment mapping to read the id from.
115| * @param {string|null} [opts.branch] - Current git branch name, if known.
116| * @returns {string|null} The task id, or null when none is discoverable.
117| ***/
118|export function resolveTaskId({ env = {}, branch = null } = {}) {
119|	const scope = env || {};
120|	for (const rawCandidate of [scope.TASK_ID, scope.KAINBAIN_TASK_ID]) {
121|		if (rawCandidate === null || rawCandidate === undefined) continue;
122|		if (String(rawCandidate).trim() === "") continue;
123|		return sanitizeTaskId(rawCandidate);
124|	}
125|	if (typeof branch === "string") {
126|		const branchName = branch.trim();
127|		if (branchName.startsWith("kb/")) {
128|			const branchTaskSegment = branchName.slice("kb/".length);
129|			if (branchTaskSegment.trim() === "") return null;
130|			return sanitizeTaskId(branchTaskSegment);
131|		}
132|	}
133|	return null;
134|}
