136|/***
137| * MARK: buildDefaultTaskScreenshotPath
138| * @description Builds the no-flag default output path for a task:
139| *   docs/tasks/<task-id>/screenshot-<YYYYMMDD-HHMMSS>.png (local time, so
140| *   each capture lands in a fresh file instead of overwriting). Throws on
141| *   an unsafe id rather than building a traversal path. Two captures
142| *   inside the same second share a name — main() hands this to
143| *   findUnusedFilePath so the second capture gains a -01 suffix instead
144| *   of overwriting the first.
145| * @example buildDefaultTaskScreenshotPath("9940bbbc", new Date(2026, 10, 16, 18, 30, 5)) => "docs/tasks/9940bbbc/screenshot-20261116-183005.png"
146| * @param {string} taskId - Resolved task id (a docs/tasks/ segment).
147| * @param {Date} [now] - Clock for the timestamp, defaults to now.
148| * @returns {string} Repo-relative default output path.
149| ***/
150|export function buildDefaultTaskScreenshotPath(taskId, now = new Date()) {
151|	const safeTaskId = sanitizeTaskId(taskId);
152|	if (!safeTaskId) {
153|		throw new Error(
154|			`Refusing to build a default screenshot path for unsafe task id ${JSON.stringify(taskId)}. `
155|			+ "Pass --out explicitly, e.g. --out docs/tasks/<task-id>/<name>-proof.png",
156|		);
157|	}
158|	const padToTwoDigits = (numberValue) => String(numberValue).padStart(2, "0");
159|	const stamp = `${now.getFullYear()}${padToTwoDigits(now.getMonth() + 1)}${padToTwoDigits(now.getDate())}`
160|		+ `-${padToTwoDigits(now.getHours())}${padToTwoDigits(now.getMinutes())}${padToTwoDigits(now.getSeconds())}`;
161|	return `docs/tasks/${safeTaskId}/screenshot-${stamp}.png`;
162|}
