164|/***
165| * MARK: findUnusedFilePath
166| * @description Picks a free file name for a default capture: the starting
167| *   path itself when nothing exists there, else the first free
168| *   <base>-01.ext, <base>-02.ext, ... so a same-second second capture
169| *   never silently overwrites the first (nothing is overwritten). Used
170| *   for the default path only — an explicit --out keeps today's exact
171| *   overwrite behavior. Pure: the existence check is injected so tests
172| *   never touch the disk.
173| * @example findUnusedFilePath({ startingPath: "a.png", fileExists: () => false }) => "a.png"
174| * @example findUnusedFilePath({ startingPath: "a.png", fileExists: (p) => p === "a.png" }) => "a-01.png"
175| * @param {Object} [opts]
176| * @param {string} opts.startingPath - First-choice path.
177| * @param {Function} opts.fileExists - Existence check ((path) => boolean).
178| * @returns {string} The starting path or the first free suffixed variant.
179| ***/
180|export function findUnusedFilePath({ startingPath, fileExists } = {}) {
181|	if (!fileExists(startingPath)) return startingPath;
182|	const fileExtension = path.extname(startingPath);
183|	const baseWithoutExtension = startingPath.slice(0, startingPath.length - fileExtension.length);
184|	for (let suffixNumber = 1; suffixNumber <= 99; suffixNumber += 1) {
185|		const candidatePath = `${baseWithoutExtension}-${String(suffixNumber).padStart(2, "0")}${fileExtension}`;
186|		if (!fileExists(candidatePath)) return candidatePath;
187|	}
188|	throw new Error(
189|		`All 99 fallback names for ${JSON.stringify(startingPath)} are taken. `
190|		+ "Pass --out explicitly, e.g. --out docs/tasks/<task-id>/<name>-proof.png",
191|	);
192|}
