236| * @param {string} opts.flagName - Flag to read, e.g. "--out".
237| * @returns {string|null} The flag's value, or null when missing.
238| ***/
239|export function readFlagValue({ args = [], flagName } = {}) {
240|	const tokens = Array.isArray(args) ? args : [];
241|	const flagIndex = tokens.indexOf(flagName);
242|	if (flagIndex === -1) return null;
